const sessionId = $json.sessionId || 'default-session';
const staticData = $getWorkflowStaticData('global');
staticData.sessions = staticData.sessions || {};
const session = staticData.sessions[sessionId] || {};
const message = ($json.chatInput || '').toString().trim();

return [{ json: { sessionId, session, message } }];

const loadJson = $('Load session').first().json;
const { session, sessionId, message } = loadJson;
const allRows = $input.all().map(i => i.json);

// Discover columns from the sheet's own data every turn — never hardcoded.
const FALLBACK_COLUMNS = ['Entry ID','Employee Code','Employee Name','Date','Project Name','Activity Type','Contributed Hours','Task Description','Additional Comments'];
const columns = allRows.length ? Object.keys(allRows[0]) : FALLBACK_COLUMNS;

const code = (session.employeeCode || '').trim().toUpperCase();
const needCode = !code;

const myRows = code
  ? allRows.filter(r => (r['Employee Code'] || '').toString().trim().toUpperCase() === code)
  : [];
const recentEntries = myRows.slice(-10).reverse();

const timezone = 'Asia/Kolkata';
const today = new Intl.DateTimeFormat('en-CA', { timeZone: timezone, year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const weekday = new Intl.DateTimeFormat('en-US', { timeZone: timezone, weekday: 'long' }).format(new Date());

// Columns the bot manages itself, never asks the employee to supply.
const systemManaged = columns.filter(c => /^(entry id|logged at|verified at|session id|channel|status|supersedes|prompt version)/i.test(c));
// Optional free-text columns (comments/notes) are never "required".
const optionalColumns = columns.filter(c => /comment|note/i.test(c));
const requiredColumns = columns.filter(c =>
  !systemManaged.includes(c) &&
  !optionalColumns.includes(c) &&
  c !== 'Employee Code' &&
  c !== 'Employee Name'
);

return [{
  json: {
    sessionId, session, message,
    columns, allRows, myRows, recentEntries,
    employeeCode: code,
    employeeName: session.employeeName || null,
    today, weekday, timezone,
    needCode,
    systemManaged, requiredColumns
  }
}];

const ctx = $json;
const rawCode = (ctx.message || '').trim().toUpperCase().replace(/[^A-Z0-9-]/g, '');
const staticData = $getWorkflowStaticData('global');
staticData.sessions = staticData.sessions || {};

if (!rawCode) {
  return [{ json: { output: "I didn't catch an Employee Code there — please type your Employee Code to get started." } }];
}

const matches = (ctx.allRows || []).filter(r => (r['Employee Code'] || '').toString().trim().toUpperCase() === rawCode);
const knownName = matches.length ? (matches[matches.length - 1]['Employee Name'] || '') : '';

staticData.sessions[ctx.sessionId] = {
  employeeCode: rawCode,
  employeeName: knownName || null,
  updatedAt: new Date().toISOString()
};

let reply;
if (knownName) {
  reply = `Welcome back, ${knownName}! You have ${matches.length} entr${matches.length === 1 ? 'y' : 'ies'} on file. What would you like to log or look up?`;
} else {
  reply = `Thanks — logging under code ${rawCode}. I don't have a name on file for you yet, so please mention your name the first time you log something (e.g. "This is Renu, log 4 hours of UX today"). What would you like to log or look up?`;
}

return [{ json: { output: reply } }];

