const out = $input.first().json;
const parsed = out.output && typeof out.output === 'object' ? out.output : out;

return [{
  json: {
    intent: parsed.intent || 'off_topic',
    entry: (parsed.entry && typeof parsed.entry === 'object') ? parsed.entry : {},
    filters: (parsed.filters && typeof parsed.filters === 'object') ? parsed.filters : {},
    target_entry_id: parsed.target_entry_id || null,
    clarification: parsed.clarification || null
  }
}];

const ai = $json;
const ctx = $('Build context').first().json;

function genEntryId() {
  const ymd = ctx.today.replace(/-/g, '');
  const rand = Math.random().toString(16).slice(2, 8).toUpperCase();
  return `WL-${ymd}-${rand}`;
}

function matchesFilters(row, filters) {
  return Object.entries(filters || {}).every(([k, v]) => {
    if (v === null || v === undefined || v === '') return true;
    const cell = (row[k] || '').toString().toLowerCase();
    return cell.includes(String(v).toLowerCase());
  });
}

let action = 'reply_only';
let reply = ai.clarification || "Sorry, I didn't quite get that — could you rephrase?";
let row = null;
let updated_row = null;
let match_entry_id = null;

if (ai.intent === 'help') {
  reply = 'I can log new work ("log 4 hours of UX for Evonsys today, did screen prototyping"), answer questions about your own entries ("how many hours this week?"), or fix a mistake ("change yesterday\'s hours to 6"). What would you like to do?';
} else if (ai.intent === 'off_topic') {
  reply = "I'm your WorkLog assistant — I can log your work hours, look up your entries, or fix a mistake. What would you like to do?";
} else if (ai.intent === 'add') {
  const entry = { ...ai.entry };
  const missingRequired = ctx.requiredColumns.filter(c => !entry[c] && entry[c] !== 0);
  if (ai.clarification || missingRequired.length) {
    reply = ai.clarification || `I still need: ${missingRequired.join(', ')}.`;
  } else {
    row = { ...entry };
    row['Entry ID'] = genEntryId();
    row['Employee Code'] = ctx.employeeCode;
    if (ctx.columns.includes('Employee Name') && !row['Employee Name']) {
      row['Employee Name'] = ctx.employeeName || 'Unknown';
    }
    if (ctx.columns.includes('Date') && !row['Date']) {
      row['Date'] = ctx.today;
    }
    action = 'append';
  }
} else if (ai.intent === 'read') {
  const filters = { ...ai.filters, 'Employee Code': ctx.employeeCode };
  const matches = ctx.allRows.filter(r => matchesFilters(r, filters));
  if (!matches.length) {
    reply = "I couldn't find any entries matching that.";
  } else {
    const hCol = ctx.columns.find(c => /hour/i.test(c));
    const totalHours = matches.reduce((sum, r) => {
      const n = Number(r[hCol]);
      return sum + (isFinite(n) ? n : 0);
    }, 0);
    const lines = matches.slice(0, 10).map(r => {
      const parts = ctx.columns.filter(c => c !== 'Employee Code').map(c => r[c]).filter(Boolean);
      return `• ${parts.join(' — ')}`;
    });
    reply = `Found ${matches.length} entr${matches.length === 1 ? 'y' : 'ies'} (${totalHours}h total):\n${lines.join('\n')}`;
    if (matches.length > 10) reply += `\n…and ${matches.length - 10} more.`;
  }
} else if (ai.intent === 'update') {
  const filters = { ...ai.filters, 'Employee Code': ctx.employeeCode };
  const matches = ai.target_entry_id
    ? ctx.allRows.filter(r => r['Entry ID'] === ai.target_entry_id)
    : ctx.allRows.filter(r => matchesFilters(r, filters));

  if (!matches.length) {
    reply = "I couldn't find an entry matching that — could you give me the Entry ID or be more specific (date, project, activity)?";
  } else if (matches.length > 1) {
    const ids = matches.slice(0, 5).map(r => r['Entry ID']).join(', ');
    reply = `That matches ${matches.length} entries. Which one — ${ids}${matches.length > 5 ? ', …' : ''}?`;
  } else {
    updated_row = { ...matches[0], ...ai.entry };
    match_entry_id = matches[0]['Entry ID'];
    action = 'update';
  }
}

return [{ json: { action, reply, row, updated_row, match_entry_id } }];

const d = $('Dispatch').first().json;
const row = d.row || {};
const parts = [];
if (row['Date']) parts.push(row['Date']);
Object.keys(row).forEach(k => {
  if (['Entry ID', 'Employee Code', 'Employee Name', 'Date'].includes(k)) return;
  if (row[k]) parts.push(`${k}: ${row[k]}`);
});
return [{ json: { output: `✅ Logged. ${parts.join(' | ')} (Entry ID ${row['Entry ID']}).` } }];
